sealed interface UiState<out T> {
    data object Loading : UiState<Nothing>       // Nothing is a subtype of everything
    data class Success<T>(val data: T) : UiState<T>
    data class Failure(val error: Throwable) : UiState<Nothing>
}

// Because of `out`, this compiles:
val state: UiState<List<User>> = UiState.Loading

fun <T> render(state: UiState<T>) = when (state) {
    UiState.Loading   -> showSpinner()
    is UiState.Success -> showData(state.data)
    is UiState.Failure -> showError(state.error)
}   // exhaustive — no else branch

