// A custom delegate: SharedPreferences-backed property
class PrefDelegate(private val prefs: SharedPreferences, private val key: String, private val default: Boolean) {
    operator fun getValue(thisRef: Any?, prop: KProperty<*>) = prefs.getBoolean(key, default)
    operator fun setValue(thisRef: Any?, prop: KProperty<*>, value: Boolean) =
        prefs.edit().putBoolean(key, value).apply()
}

